import SafariServices
import SwiftUI

/// The client and companion offer the same installation guidance and destinations.
/// Browser behavior and the optional app-connection reader live in the WXT repo.
public struct BrowserExtensionSetup: View {
    @Environment(\.openURL) private var openURL
    @State private var errorMessage: String?
    @State private var showSafariSetup = false
    private let title: String
    public init(title: String = "Browser Extension") { self.title = title }

    #if os(macOS)
    @MainActor public static func openSafariSettings(completion: @escaping @MainActor (Error?) -> Void) {
        // Safari requires this call to come from the app that contains the extension.
        // The server companion delegates to that app through its navigation URL.
        if Bundle.main.bundleIdentifier == "io.archivebox.ArchiveBox" {
            SFSafariApplication.showPreferencesForExtension(withIdentifier: "io.archivebox.ArchiveBox.Safari") { error in
                Task { @MainActor in completion(error) }
            }
            return
        }
        let workspace = NSWorkspace.shared
        let app = AppInformation.installedClientURL
        guard let app else {
            completion(NSError(domain: "ArchiveBox", code: 1, userInfo: [NSLocalizedDescriptionKey: "Install ArchiveBox.app first; it contains the Safari extension."]))
            return
        }
        workspace.open([URL(string: "archivebox://safari-extension-settings")!], withApplicationAt: app,
                       configuration: NSWorkspace.OpenConfiguration()) { _, error in
            Task { @MainActor in completion(error) }
        }
    }
    #endif

    public var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            GroupBox(title) {
                VStack(alignment: .leading, spacing: 12) {
                    Text(
                        "Import browser bookmarks or history, save URLs by clicking the extension icon, and include cookies for authenticated pages. Choose your browser to install or enable ArchiveBox."
                    )
                    ScrollView(.horizontal) {
                        HStack(spacing: 8) {
                            #if os(macOS)
                                Button("Safari", systemImage: "safari") {
                                    showSafariSetup = true
                                }
                                .alert("Enable ArchiveBox in Safari", isPresented: $showSafariSetup) {
                                    Button("Cancel", role: .cancel) {}
                                    Button("OK") {
                                        Self.openSafariSettings { error in
                                            if let error { Task { @MainActor in errorMessage = error.localizedDescription } }
                                        }
                                    }
                                } message: {
                                    Text("Open Safari → Settings → Extensions, select ArchiveBox, and enable its checkbox. Choose which websites ArchiveBox can access.\n\nClick OK to open Safari’s extension settings. If it opens on a different page, follow the steps above.")
                                }
                            #else
                                if #available(iOS 26.2, *) {
                                    Button("Safari", systemImage: "safari") {
                                        showSafariSetup = true
                                    }
                                    .alert("Enable ArchiveBox in Safari", isPresented: $showSafariSetup) {
                                        Button("Cancel", role: .cancel) {}
                                        Button("OK") {
                                            SFSafariSettings.openExtensionsSettings(forIdentifiers: ["io.archivebox.ArchiveBox.Safari"]) { error in
                                                if let error { errorMessage = error.localizedDescription }
                                            }
                                        }
                                    } message: {
                                        Text("Open Settings → Apps → Safari → Extensions → ArchiveBox, then turn on Allow Extension. Choose which websites ArchiveBox can access.\n\nTap OK to open Settings. If it opens on a different page, follow the steps above.")
                                    }
                                }
                            #endif
                            ForEach(
                                [
                                    ("Chrome", "Chrome", "https://chromewebstore.google.com/detail/archivebox/habonpimjphpdnmcfkaockjnffodikoj"),
                                    ("Brave", "Brave", "https://chromewebstore.google.com/detail/archivebox/habonpimjphpdnmcfkaockjnffodikoj"),
                                    ("Firefox", "Firefox", "https://addons.mozilla.org/firefox/addon/archivebox-exporter/"),
                                    ("Source Code", "GitHubMark", "https://github.com/ArchiveBox/archivebox-browser-extension"),
                                ], id: \.0
                            ) { name, icon, address in
                                Button {
                                    openURL(URL(string: address)!)
                                } label: {
                                    Label {
                                        Text(name)
                                    } icon: {
                                        Image(icon).resizable().scaledToFit().frame(width: 16, height: 16)
                                    }
                                }
                            }
                        }
                        .buttonStyle(.bordered)
                        .fixedSize(horizontal: true, vertical: false)
                    }
                    #if !os(macOS)
                        if #unavailable(iOS 26.2) {
                            Text("Safari: Settings → Apps → Safari → Extensions → ArchiveBox")
                                .font(.footnote).foregroundStyle(.secondary)
                        }
                    #endif
                    Text(
                        "Safari can use the connection saved in ArchiveBox.app or its own extension options. For Chrome, Brave, and Firefox, configure the extension directly. Brave uses the Chrome Web Store."
                    )
                    .font(.footnote).foregroundStyle(.secondary)
                }
            }
            if let errorMessage { Text(errorMessage).foregroundStyle(.red).textSelection(.enabled) }
        }
    }
}

import Foundation
import WebKit

/// Every embedded page in an app shares this store. Only the API key is durable;
/// browser credentials are issued by Django and remain in memory.
@MainActor public final class BrowserAuthentication {
    public let dataStore = WKWebsiteDataStore.nonPersistent()
    private let client = ArchiveBoxClient()
    private struct Credentials: Equatable { let server: URL; let token: String }
    private var credentials: Credentials?
    private var session: BrowserSession?
    private var pending: Task<Void, Error>?
    private var generation = UUID()

    public init() {}
    public var adminURL: URL? { session?.admin_url }

    public func authenticatedPageURL(_ url: URL) -> URL {
        guard let server = credentials?.server, let admin = session?.admin_url,
              url.scheme == server.scheme, url.host == server.host, url.port == server.port,
              url.path == "/add" || url.path == "/admin" || url.path.hasPrefix("/admin/"),
              var result = URLComponents(url: url, resolvingAgainstBaseURL: false) else { return url }
        result.scheme = admin.scheme; result.host = admin.host; result.port = admin.port
        return result.url ?? url
    }

    /// Only the configured control origin (or its exact admin sibling) may hand
    /// credentials to the app. The broader replay/navigation boundary is not enough.
    public nonisolated static func isTrustedAdminPage(_ url: URL, server: URL) -> Bool {
        guard ["http", "https"].contains(server.scheme ?? ""), url.scheme == server.scheme,
              url.user == nil, url.password == nil,
              (url.port ?? (url.scheme == "https" ? 443 : 80)) == (server.port ?? (server.scheme == "https" ? 443 : 80)),
              let host = url.host?.lowercased(), let configuredHost = server.host?.lowercased(),
              (url.path == "/admin" || url.path.hasPrefix("/admin/")),
              !url.path.hasPrefix("/admin/login"), !url.path.hasPrefix("/admin/logout") else { return false }
        if host == configuredHost { return true }
        guard !configuredHost.contains(":"), !configuredHost.split(separator: ".").allSatisfy({ UInt8($0) != nil }) else { return false }
        let prefix = ["api.", "admin.", "web."].first { configuredHost.hasPrefix($0) }
        let base = prefix.map { String(configuredHost.dropFirst($0.count)) } ?? configuredHost
        return host == "admin." + base
    }

    /// Admin templates already create/reuse this user's key for their REST widgets.
    /// Read that existing value from the main frame; never export cookies or widen REST auth.
    public func apiKey(from webView: WKWebView, server: URL) async throws -> String? {
        guard webView.configuration.websiteDataStore === dataStore,
              let url = webView.url, Self.isTrustedAdminPage(url, server: server) else { return nil }
        let value = try await webView.callAsyncJavaScript("""
            if (window.location.href !== pageURL) return null;
            const key = window.ARCHIVEBOX_API_KEY;
            return typeof key === 'string' && key.trim() ? key.trim() : null;
            """, arguments: ["pageURL": url.absoluteString], in: nil, contentWorld: .page)
        try Task.checkCancellation()
        guard webView.url == url, Self.isTrustedAdminPage(url, server: server) else { return nil }
        return value as? String
    }

    public func authenticate(server: URL, token: String, force: Bool = false) async throws {
        let configuration = Credentials(server: server, token: token)
        if !force, credentials == configuration,
           let session, session.cookie.expires > Date().timeIntervalSince1970 + 60 { return }
        if credentials == configuration, let pending { try await pending.value; return }
        let changed = credentials != configuration
        pending?.cancel()
        credentials = configuration
        let generation = UUID()
        self.generation = generation
        let task = Task { @MainActor in
            var phase = "clear-previous-web-data"
            do {
                if changed {
                    await dataStore.removeData(ofTypes: WKWebsiteDataStore.allWebsiteDataTypes(), modifiedSince: .distantPast)
                    session = nil
                }
                phase = "check-cancellation-before-browser-session"
                try Task.checkCancellation()
                phase = "request-browser-session"
                let login = try await client.browserSession(server: server, token: token)
                phase = "check-cancellation-after-browser-session"
                try Task.checkCancellation()
                phase = "validate-browser-session"
                guard self.generation == generation else { throw CancellationError() }
                guard let host = login.admin_url.host, ["http", "https"].contains(login.admin_url.scheme ?? ""),
                      login.cookie.expires > Date().timeIntervalSince1970 else {
                    throw ArchiveBoxError.message("The server returned an invalid browser session.")
                }
                phase = "create-session-cookie"
                var properties: [HTTPCookiePropertyKey: Any] = [
                    .name: login.cookie.name, .value: login.cookie.value, .domain: host, .path: "/",
                    .expires: Date(timeIntervalSince1970: login.cookie.expires),
                    HTTPCookiePropertyKey("HttpOnly"): "TRUE",
                ]
                if login.cookie.secure { properties[.secure] = "TRUE" }
                guard let cookie = HTTPCookie(properties: properties) else {
                    throw ArchiveBoxError.message("The server returned an invalid session cookie.")
                }
                phase = "store-session-cookie"
                await dataStore.httpCookieStore.setCookie(cookie)
                session = login
                NSLog("ArchiveBox browser authentication completed phase=%@", phase)
            } catch {
                Self.logAuthenticationFailure(phase, error: error)
                throw error
            }
        }
        pending = task
        defer { if self.generation == generation { pending = nil } }
        try await task.value
    }

    private static func logAuthenticationFailure(_ phase: String, error: Error) {
        let details = error as NSError
        NSLog("ArchiveBox browser authentication failed phase=%@ type=%@ domain=%@ code=%ld cancelled=%d",
              phase, String(reflecting: type(of: error)), details.domain, details.code,
              Task.isCancelled ? 1 : 0)
    }

    public func sidebarProgress(server: URL, token: String) async throws -> SidebarProgress {
        try await authenticate(server: server, token: token)
        guard let session else { throw ArchiveBoxError.message("The admin session is unavailable.") }
        let origin = try ServerAddress.normalize(session.admin_url.absoluteString)
        guard !session.cookie.secure || origin.scheme == "https" else {
            throw ArchiveBoxError.message("The admin session requires HTTPS.")
        }
        return try await client.sidebarProgress(server: origin, cookie: "\(session.cookie.name)=\(session.cookie.value)")
    }

    public func clear() async {
        generation = UUID()
        pending?.cancel(); pending = nil; credentials = nil; session = nil
        await dataStore.removeData(ofTypes: WKWebsiteDataStore.allWebsiteDataTypes(), modifiedSince: .distantPast)
    }
}

